        public TermsForm()
        {
            InitializeComponent();
            textBox1.Text = "ОБЩИ УСЛОВИЯ ЗА ПОЛЗВАНЕ НА СОФТУЕРНИЯ ПРОДУКТ („ПРАВИЛА И СЪГЛАСИЯ“)\r\nПоследна актуализация: 31 май 2026 г.\r\n\r\n1. ПРАВНО ОБВЪРЗВАЩО СПОРАЗУМЕНИЕ\r\nНастоящият документ представлява пълно, окончателно и юридически обвързващо споразумение (наричано по-долу „Споразумението“) между Крайния потребител (наричан по-долу „Потребител“) и разработчика/собственика на софтуерното приложение (наричано по-долу „Програмата“). С натискането на бутона „Приемам“, инсталирането, копирането или използването на Програмата по какъвто и да е начин, Потребителят безусловно се съгласява с всички клаузи, подклаузи, анекси и допълнения, изложени тук. Ако Потребителят не е съгласен с дори една от точките, той е длъжен незабавно да прекрати инсталацията и да премахне всички свързани файлове от своите устройства.\r\n\r\n2. ПРЕДОСТАВЯНЕ НА ЛИЦЕНЗ И ОГРАНИЧЕНИЯ\r\n2.1. Собственикът предоставя на Потребителя ограничен, неизключителен, непрехвърляем, оттегляем лиценз за използване на Програмата за лични и нетърговски цели, при стриктно спазване на настоящите Общи условия.\r\n2.2. Потребителят няма право (и няма право да разрешава на трети лица) да:\r\nа) Модифицира, декомпилира, разглобява (disassemble), извършва обратно инженерство (reverse engineering) или прави опити за извличане на изходния код на Програмата;\r\nб) Преотстъпва подлицензи, да дава под наем, да лизингова, да разпространява или да прехвърля правата върху софтуера на трети страни без изрично писмено съгласие;\r\nв) Премахва, променя или закрива каквито и да било съобщения за авторски права, търговски марки или други права на собственост, вградени в Програмата;\r\nг) Използва софтуера за създаване на производни продукти, конкурентни приложения или за каквито и да било автоматизирани скриптови процеси без разрешение.\r\n\r\n3. ИНТЕЛЕКТУАЛНА СОБСТВЕНОСТ\r\nВсички права, заглавия и интереси върху Програмата, включително, но не само: софтуерният код, графичният интерфейс, логата на браузърите (доколкото са реферирани или интегрирани чрез външни библиотеки), документацията и всички свързани функционалности, са и остават изключителна собственост на Разработчика. Програмата е защитена от местното законодателство за авторското право и международните договори.\r\n\r\n4. ИЗКЛЮЧВАНЕ НА ГАРАНЦИИ (ОГРАНИЧЕНИЕ НА ОТГОВОРНОСТТА)\r\n4.1. ПРОГРАМАТА СЕ ПРЕДОСТАВЯ НА ПРИНЦИПА „КАКТО Е“ (AS IS) И „КОЛКОТО Е НАЛИЧНА“ (AS AVAILABLE), БЕЗ КАКВИТО И ДА БИЛО ИЗРИЧНИ ИЛИ ПОДРАЗБИРАЩИ СЕ ГАРАНЦИИ, ВКЛЮЧИТЕЛНО, НО НЕ САМО, ПОДРАЗБИРАЩИТЕ СЕ ГАРАНЦИИ ЗА ПРОДАВАЕМОСТ, ПРИГОДНОСТ ЗА ОПРЕДЕЛЕНА ЦЕЛ ИЛИ НЕПОРУШЕНИЕ НА ПРАВА.\r\n4.2. Разработчикът не гарантира, че функциите, съдържащи се в Програмата, ще отговорят на изискванията на Потребителя, че работата на софтуера ще бъде непрекъсната или безгрешна, или че евентуалните дефекти ще бъдат отстранени своевременно.\r\n4.3. До максималната степен, разрешена от приложимото законодателство, Разработчикът в никакъв случай не носи отговорност за каквито и да било преки, косвени, случайни, специални или последващи вреди (включително, без ограничение, щети от загуба на бизнес печалби, прекъсване на дейността, загуба на бизнес информация, системни сривове или други материални и нематериални загуби), произтичащи от използването или невъзможността за използване на Програмата, дори ако Разработчикът е бил уведомен за възможността от такива щети.\r\n\r\n5. СЪБИРАНЕ НА ДАННИ И ПОВЕРИТЕЛНОСТ\r\nПотребителят се съгласява, че Програмата може автоматично да събира техническа, диагностична и статистическа информация, свързана с вашето устройство, операционна система и избраните конфигурации на браузъри, с цел подобряване на стабилността на приложението. Всички събрани данни се обработват в съответствие с вътрешните правила за конфиденциалност и няма да бъдат споделяни с трети лица, освен ако това не се изисква по закон.\r\n\r\n6. ПРЕКРАТЯВАНЕ НА СПОРАЗУМЕНИЕТО\r\nНастоящото Споразумение е в сила до неговото прекратяване. Правата на Потребителя по този лиценз се прекратяват автоматично без предизвестие от страна на Разработчика, ако Потребителят не спази което и да е от условията, посочени тук. При прекратяване на Споразумението, Потребителят е длъжен да преустанови всякаква употреба на Програмата и да унищожи всички нейни копия.\r\n\r\n7. ПРИЛОЖИМО ПРАВО И РАЗРЕШАВАНЕ НА СПОРОВЕ\r\nВсички спорове, възникнали във връзка с тълкуването или изпълнението на настоящото Споразумение, ще бъдат решавани по пътя на преговорите. В случай че не се постигне съгласие, спорът ще бъде отнесен за разрешаване пред компетентния съд по местонахождение на Разработчика, съгласно приложимото местно законодателство.\r\n\r\n8. ИЗМЕНЕНИЯ НА УСЛОВИЯТА\r\nРазработчикът си запазва правото да променя, актуализира или допълва тези Общи условия по всяко време без предварително известие. Продължаването на употребата на Програмата след направените промени означава, че Потребителят приема новите условия.\r\n\r\nС натискането на бутона „Приемам“, вие потвърждавате, че сте прочели, разбрали и сте съгласни с тези условия.\r\n\r\n\r\n" +
                "ДОПЪЛНИТЕЛНО СПОРАЗУМЕНИЕ ЗА ОГРАНИЧАВАНЕ НА ОТГОВОРНОСТТА И ЛИПСА НА ГАРАНЦИИ ЗА ФУНКЦИОНАЛНОСТ\r\nПоследна актуализация: 31 май 2026 г.\r\n\r\n1. ВАЖНО СЪОБЩЕНИЕ ОТНОСНО ТЕСТВАНЕТО НА СОФТУЕРА\r\nПотребителят изрично се уведомява, потвърждава и приема факта, че настоящият софтуерен продукт (наричан по-долу „Програмата“) се намира в експериментален етап на разработка. Разработчикът НЕ е тествал функционалностите на Програмата в реална среда, не е провеждал тестове за съвместимост и стабилност и няма абсолютно никаква представа дали софтуерът функционира правилно, частично или изобщо не работи на устройството на Крайния потребител.\r\n\r\n2. ПЪЛЕН ОТКАЗ ОТ ОТГОВОРНОСТ ПРИ ЩЕТИ НА ОПЕРАЦИОННАТА СИСТЕМА\r\nРазработчикът на този софтуер не носи абсолютно никаква отговорност (пряка, косвена, материална или нематериална) за каквито и да било повреди, сривове, системни грешки или пълно унищожаване на операционната система (Operating System) на потребителя. Това включва, но не се ограничава до: засягане на системните регистри (Registry), изтриване на критични за Windows файлове, повреда на драйвери, софтуерни конфликти с инсталираните браузъри (Chrome, Brave, Opera GX, Tor) или хардуерни аварии, възникнали вследствие на стартирането на това приложение.\r\n\r\n3. ПОЕМАНЕ НА РИСКА ОТ ПОТРЕБИТЕЛЯ (AT YOUR OWN RISK)\r\nС натискането на бутона „Приемам“, вие декларирате, че стартирате тази Програма изцяло на свой собствен риск и отговорност. В случай че Програмата причини вреда на вашия компютър, загуба на данни, заразяване или софтуерен срив, който изисква преинсталация на операционната система, всички разходи по ремонта, възстановяването на информацията и техническата поддръжка са ИЗЦЯЛО за сметка на Потребителя. Разработчикът не дължи компенсации, обезщетения или техническа помощ под никаква форма.\r\n\r\n4. БЕЗУСЛОВНО СЪГЛАСИЕ\r\nАко не сте съгласни да поемете пълния риск за стабилността на вашата операционна система и компютърна конфигурация, сте длъжни незабавно да натиснете бутона „Отказвам“ (Decline) и да затворите това приложение. Продължаването напред служи като писмено доказателство, че сте разбрали липсата на тестове и освобождавате разработчика от всякакви правни претенции.\r\n";

        }

        private void btnAccept_Click(object sender, EventArgs e)
        {
            this.DialogResult = DialogResult.OK;
            this.Close();
        }

        private void btnReject_Click(object sender, EventArgs e)
        {
            this.DialogResult = DialogResult.Cancel;
            this.Close();
        }
    }
